-- 从设备 (b95ffa0c) eta.db 原样导出的 v39 残缺结构：identity_hash 9a4c19ff55cb624e0c9a5bf7c5250992
-- user_version=39；conversations 缺 dispatch_managed_at，dispatch_claims 不存在。
CREATE TABLE android_metadata (locale TEXT);
CREATE TABLE `conversation_context_checkpoints` (`conversation_id` TEXT NOT NULL, `history_json` TEXT NOT NULL, `cloud_usage_json` TEXT NOT NULL DEFAULT '', PRIMARY KEY(`conversation_id`), FOREIGN KEY(`conversation_id`) REFERENCES `conversations`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `conversation_folders` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `sort_index` INTEGER NOT NULL, `created_at` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE `conversation_messages` (`id` TEXT NOT NULL, `conversation_id` TEXT NOT NULL, `sort_index` INTEGER NOT NULL, `type` TEXT NOT NULL, `content` TEXT NOT NULL, `images_json` TEXT NOT NULL, `is_edited` INTEGER NOT NULL DEFAULT 0, `render_markdown` INTEGER, `context_tokens` INTEGER, `input_tokens` INTEGER, `output_tokens` INTEGER, `reasoning_tokens` INTEGER, `cached_tokens` INTEGER, `elapsed_seconds` INTEGER, `tool_name` TEXT, `tool_status` TEXT, `arguments_summary` TEXT, `result_summary` TEXT, `image_count` INTEGER NOT NULL, `tools_json` TEXT NOT NULL, `generated_at_millis` INTEGER, arguments_detail TEXT, result_detail TEXT, media_json TEXT NOT NULL DEFAULT '[]', PRIMARY KEY(`id`), FOREIGN KEY(`conversation_id`) REFERENCES `conversations`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `conversation_state` (`id` TEXT NOT NULL, `selected_conversation_id` TEXT NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE `conversations` (`id` TEXT NOT NULL, `title` TEXT NOT NULL, `thinking_enabled` INTEGER NOT NULL, `reasoning_effort` TEXT NOT NULL DEFAULT 'default', `history_json` TEXT NOT NULL, `applied_runtime_run_ids_json` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, `folder_id` TEXT NOT NULL DEFAULT '', `is_pinned` INTEGER NOT NULL DEFAULT 0, `has_completion_marker` INTEGER NOT NULL DEFAULT 0, `provider_id` TEXT NOT NULL DEFAULT '', `model_id` TEXT NOT NULL DEFAULT '', `assistant_id` TEXT NOT NULL DEFAULT '', `deleted_at` INTEGER, dispatch_parent_id TEXT, PRIMARY KEY(`id`));
CREATE TABLE `mcp_servers` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `url` TEXT NOT NULL, `enabled` INTEGER NOT NULL, `protocol_mode` TEXT NOT NULL, `authorization_type` TEXT NOT NULL, `tools_json` TEXT NOT NULL, `enabled_tool_names_json` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `sort_order` INTEGER NOT NULL, `last_refreshed_at` INTEGER, `last_protocol_version` TEXT, `tools_expire_at` INTEGER, PRIMARY KEY(`id`));
CREATE TABLE `media_index` (`source_key` TEXT NOT NULL, `model_id` TEXT NOT NULL, `vector_dim` INTEGER NOT NULL, `kind` TEXT NOT NULL, `display_name` TEXT NOT NULL, `mime` TEXT NOT NULL, `size_bytes` INTEGER NOT NULL, `modified_at` INTEGER NOT NULL, `content_hash` TEXT NOT NULL, `duration_ms` INTEGER, `width` INTEGER, `height` INTEGER, `frame_time_ms` INTEGER, `thumb_path` TEXT, `vector` BLOB NOT NULL, `indexed_at` INTEGER NOT NULL, PRIMARY KEY(`source_key`, `model_id`, `vector_dim`));
CREATE TABLE `media_source` (`id` TEXT NOT NULL, `type` TEXT NOT NULL, `uri` TEXT NOT NULL, `label` TEXT NOT NULL, `enabled` INTEGER NOT NULL, `last_scan_at` INTEGER, `item_count` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE `model_providers` (`id` TEXT NOT NULL, `type` TEXT NOT NULL, `name` TEXT NOT NULL, `base_url` TEXT NOT NULL, `api_key` TEXT NOT NULL, `is_enabled` INTEGER NOT NULL, `is_built_in` INTEGER NOT NULL, `sort_order` INTEGER NOT NULL, `system_prompt` TEXT, `custom_headers_json` TEXT NOT NULL, `custom_body_json` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `endpoint_mode` TEXT NOT NULL, `hosted_web_search_enabled` INTEGER NOT NULL DEFAULT 0, `responses_strip_reasoning_status` INTEGER NOT NULL DEFAULT 0, `anthropic_version` TEXT NOT NULL, `balance_option_json` TEXT NOT NULL DEFAULT '{}', `auth_mode` TEXT NOT NULL DEFAULT 'api_key', `session_gateway_json` TEXT NOT NULL DEFAULT '', PRIMARY KEY(`id`));
CREATE TABLE `provider_models` (`id` TEXT NOT NULL, `provider_id` TEXT NOT NULL, `model_id` TEXT NOT NULL, `display_name` TEXT NOT NULL, `is_enabled` INTEGER NOT NULL, `is_built_in` INTEGER NOT NULL, `sort_order` INTEGER NOT NULL, `owned_by` TEXT, `context_window` INTEGER, `context_window_override` INTEGER, `input_modalities_json` TEXT NOT NULL, `output_modalities_json` TEXT NOT NULL, `attachment` INTEGER, `vision_override` INTEGER, `tool_call` INTEGER, `reasoning` INTEGER, `reasoning_capabilities_json` TEXT NOT NULL DEFAULT 'null', `reasoning_override` INTEGER, `reasoning_capabilities_override_json` TEXT NOT NULL DEFAULT 'null', `preferred_reasoning_effort` TEXT, `structured_output` INTEGER, `supports_temperature` INTEGER, `custom_headers_json` TEXT NOT NULL, `custom_body_json` TEXT NOT NULL, `source` TEXT NOT NULL, `created_at` INTEGER NOT NULL, PRIMARY KEY(`id`), FOREIGN KEY(`provider_id`) REFERENCES `model_providers`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE room_master_table (id INTEGER PRIMARY KEY,identity_hash TEXT);
CREATE TABLE `runtime_archive_events` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `archive_run_id` TEXT NOT NULL, `sort_index` INTEGER NOT NULL, `event_json` TEXT NOT NULL, FOREIGN KEY(`archive_run_id`) REFERENCES `runtime_archive_runs`(`archive_run_id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `runtime_archive_runs` (`archive_run_id` TEXT NOT NULL, `run_id` TEXT NOT NULL, `handoff_id` TEXT NOT NULL, `handoff_source` TEXT NOT NULL, `handoff_payload` TEXT NOT NULL, `dismiss_entry_surface` INTEGER NOT NULL, `ok` INTEGER NOT NULL, `content` TEXT NOT NULL, `error` TEXT, `reasoning_content` TEXT NOT NULL, `transcript_json` TEXT NOT NULL, `user_image_previews_json` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `virtual_delivery_completed` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`archive_run_id`));
CREATE TABLE `runtime_inflight_events` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `run_id` TEXT NOT NULL, `sort_index` INTEGER NOT NULL, `event_json` TEXT NOT NULL, FOREIGN KEY(`run_id`) REFERENCES `runtime_inflight_runs`(`run_id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `runtime_inflight_runs` (`run_id` TEXT NOT NULL, `owner_instance_id` TEXT NOT NULL, `handoff_id` TEXT NOT NULL, `handoff_source` TEXT NOT NULL, `handoff_payload` TEXT NOT NULL, `dismiss_entry_surface` INTEGER NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, `recovery_incomplete` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`run_id`));
CREATE TABLE `runtime_results` (`run_id` TEXT NOT NULL, `handoff_id` TEXT NOT NULL, `handoff_source` TEXT NOT NULL, `handoff_payload` TEXT NOT NULL, `dismiss_entry_surface` INTEGER NOT NULL, `ok` INTEGER NOT NULL, `content` TEXT NOT NULL, `error` TEXT, `reasoning_content` TEXT NOT NULL, `transcript_json` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `virtual_delivery_completed` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`run_id`));
CREATE TABLE `skill_registry` (`skill_id` TEXT NOT NULL, `enabled` INTEGER NOT NULL, `source` TEXT NOT NULL, `install_state` TEXT NOT NULL, PRIMARY KEY(`skill_id`));
CREATE INDEX `index_conversation_messages_conversation_id` ON `conversation_messages` (`conversation_id`);
CREATE UNIQUE INDEX `index_conversation_messages_conversation_id_sort_index` ON `conversation_messages` (`conversation_id`, `sort_index`);
CREATE INDEX `index_media_index_kind` ON `media_index` (`kind`);
CREATE INDEX `index_media_index_modified_at` ON `media_index` (`modified_at`);
CREATE INDEX `index_provider_models_provider_id` ON `provider_models` (`provider_id`);
CREATE INDEX `index_provider_models_provider_id_sort_order` ON `provider_models` (`provider_id`, `sort_order`);
CREATE INDEX `index_runtime_archive_events_archive_run_id` ON `runtime_archive_events` (`archive_run_id`);
CREATE UNIQUE INDEX `index_runtime_archive_events_archive_run_id_sort_index` ON `runtime_archive_events` (`archive_run_id`, `sort_index`);
CREATE INDEX `index_runtime_inflight_events_run_id` ON `runtime_inflight_events` (`run_id`);
CREATE UNIQUE INDEX `index_runtime_inflight_events_run_id_sort_index` ON `runtime_inflight_events` (`run_id`, `sort_index`);
